.roc-lane-heading{height:44px;width:100%;display:flex;align-items:center;gap:10px;padding:0 16px;background:none;border:0;border-bottom:1px solid var(--roc-line);font-size:12px!important;text-align:left;white-space:nowrap}.roc-lane-dot,.roc-event-dot{flex:none;display:block;width:9px;height:9px;background:var(--lane-color);border-radius:2px}
.roc-lane-title,.roc-event-label{opacity:0;transition:opacity .18s}.is-focused .roc-lane-title,.is-focused .roc-event-label{opacity:1}
.roc-lane-events{position:relative}.roc-lane-event{position:absolute;left:0;right:0;height:38px;display:flex;align-items:center;gap:12px;text-align:left;border:0;background:none;padding:0 16px;overflow:hidden;white-space:nowrap;font-size:11px!important}.roc-lane-event:hover,.roc-lane-event.is-selected{background:#edf0e7}.roc-event-dot{width:12px;height:18px}.roc-event-label{white-space:nowrap}
.roc-tabs{position:relative;display:inline-flex;border:1px solid var(--roc-line);padding:4px;border-radius:9px;background:#f0f1eb;max-width:100%}
.roc-tabs button{position:relative;z-index:1;background:none;border:0;padding:11px 18px;font-size:12px;border-radius:5px;white-space:nowrap}.roc-tabs button[data-active=true]{color:#2c4227}
.roc-tab-marker{position:absolute;left:0;top:4px;bottom:4px;border-radius:5px;background:#fff;box-shadow:0 1px 4px #20282012;transition:transform .36s cubic-bezier(.22,.8,.25,1),width .36s cubic-bezier(.22,.8,.25,1)}
@media(max-width:480px){.roc-folder-card{width:94px;padding:12px;height:145px}.roc-folder-card strong{font-size:17px}.roc-folder-back{width:190px}.roc-folder-toggle{width:205px}.roc-source{width:105px;padding:12px}.roc-source h3{font-size:16px}.roc-tabs button{padding:10px 12px}.roc-expand{padding:20px 12px}}
@media(prefers-reduced-motion:reduce){.roc-folder *,.roc-sources *,.roc-lanes *,.roc-tabs *{transition:none!important;animation:none!important}}
/* Configurable surfaces. Geometry stays inside the same retained collection. */
.roc-folder{height:340px;max-width:500px;container-type:inline-size}
.roc-folder-back{left:50%;top:49%;width:210px;height:150px;background:color-mix(in srgb,var(--folder-color,#a8c6ee),#454d5c 13%);border:1px solid #ffffff50;box-shadow:inset 0 1px #ffffff70;transition:left var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1)}
.roc-folder-back:before{width:80px;top:-14px;height:25px}
.roc-folder-card{width:118px;height:152px;padding:12px;border:1px solid #ffffff70;border-radius:9px;box-shadow:0 5px 14px #22222216;transform-origin:center;transition:left var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),top var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),transform var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),box-shadow .2s}
.roc-folder-card:hover{box-shadow:0 13px 24px #22222220}.roc-folder-card strong{font-size:20px}.roc-card-content{margin-top:12px}
.roc-folder-toggle{left:50%;top:58%;width:228px;height:133px;padding:22px;border:1px solid #ffffff90;border-radius:9px 9px 19px 19px;transform:translateX(-50%);transform-origin:50% 100%;background:var(--folder-color,#a8c6ee);box-shadow:inset 0 1px 1px #ffffff70,0 14px 24px #2933420c;transition:transform var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),left var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),background .25s}
.roc-folder-toggle>span:first-child{font-size:13px}.roc-folder-toggle>span:last-child{color:#273344a6}
.roc-folder[data-material=glass] .roc-folder-toggle{background:color-mix(in srgb,var(--folder-color,#a8c6ee) 67%,transparent);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
.roc-folder.is-open .roc-folder-toggle{background:var(--folder-color,#a8c6ee);transform:translateX(-50%) perspective(650px) rotateX(-24deg)}
.roc-folder.is-open[data-material=glass] .roc-folder-toggle{background:color-mix(in srgb,var(--folder-color,#a8c6ee) 67%,transparent)}
.roc-folder[data-direction=right] .roc-folder-back,.roc-folder[data-direction=right] .roc-folder-toggle{left:28%;width:162px}
.roc-folder[data-direction=right] .roc-folder-toggle{transform-origin:0% 50%}
.roc-folder[data-direction=right].is-open .roc-folder-toggle{transform:translateX(-50%) perspective(650px) rotateY(-26deg)}
.roc-source{transition:transform var(--roc-duration,480ms) cubic-bezier(.22,.8,.25,1),opacity .3s}
.roc-lane{transition:flex-basis var(--roc-duration,480ms) cubic-bezier(.22,.8,.25,1),flex-grow var(--roc-duration,480ms) cubic-bezier(.22,.8,.25,1)}
.roc-tab-marker{transition:transform var(--roc-duration,360ms) cubic-bezier(.22,.8,.25,1),width var(--roc-duration,360ms) cubic-bezier(.22,.8,.25,1);background:var(--roc-marker,#fff)}
@container(max-width:350px){.roc-folder-card{width:94px;height:143px}.roc-folder-card strong{font-size:17px}.roc-folder-toggle{width:200px}.roc-folder-back{width:190px}.roc-folder[data-direction=right] .roc-folder-toggle,.roc-folder[data-direction=right] .roc-folder-back{width:132px}.roc-folder[data-direction=right] .roc-folder-toggle{padding:16px}}
@media(prefers-reduced-motion:reduce){.roc-folder *,.roc-source,.roc-lane,.roc-tab-marker{transition:none!important}}
/* Retained reading composition. Native top-layer promotion avoids transformed
   ancestor clipping without moving or remounting the editor subtree. */
.roc-card-preview{width:100%;position:relative;color:var(--roc-ink,#2c302c)}
.roc-return-slot{position:relative;width:100%}
.roc-card-dialog{position:absolute;inset:0;width:100%;height:100%;max-width:none;max-height:none;padding:0;margin:0;border:0;overflow:visible;background:transparent;color:inherit;box-sizing:border-box}
.roc-card-dialog:not([open]){display:none}
.roc-card-dialog.is-reading{position:fixed;inset:0;width:100vw;height:100dvh;overflow:hidden}
.roc-card-dialog::backdrop{background:rgb(244 241 234 / calc(var(--roc-reveal,0)*.78));backdrop-filter:blur(calc(var(--roc-reveal,0)*10px))}
.roc-preview-paper{position:absolute;left:0;top:0;margin:0;background:var(--roc-card-color,#fcfbf8);border:1px solid #e1dfd4;box-shadow:0 2px 5px #252d2108,0 12px 32px #252d210a;overflow:clip;transform-origin:0 0}
.roc-preview-scroll{width:100%;overflow:hidden;overscroll-behavior:contain;scrollbar-width:thin}
.roc-preview-extent{position:relative;width:100%}
.roc-preview-composition{position:absolute;left:0;top:0;transform-origin:0 0;padding:38px;font-size:16px;line-height:1.75;font-family:inherit;box-sizing:border-box}
.roc-preview-composition h3{font:normal 32px/1.2 Georgia,serif;margin:20px 0;letter-spacing:-.025em}
.roc-preview-composition .roc-eyebrow{font-size:11px}
.roc-preview-composition .roc-paper-body{height:auto;visibility:visible;overflow:visible;font-size:16px;line-height:1.75}
.roc-preview-composition .roc-source-content{max-height:none;overflow:visible;font-size:16px;line-height:1.75}
.roc-preview-close{position:fixed;right:max(24px,env(safe-area-inset-right));top:max(16px,env(safe-area-inset-top));border:1px solid #dddcd4;background:#fcfbf8f0;border-radius:24px;padding:10px 16px;font:13px system-ui!important;z-index:1;opacity:var(--roc-reveal,0)}
.roc-preview-trigger{position:relative;min-height:36px;margin-top:8px}
.roc-expand>.roc-card-preview{max-width:250px}
.roc-source{padding:0!important;border:0;background:transparent;box-shadow:none;border-radius:0;min-height:0}
.roc-source .roc-preview-composition h3{font-size:30px}
.roc-source .roc-preview-trigger{font-size:11px!important}
.roc-preview-composition .mini-landscape{height:160px}
/* Extracted media and contextual controls. */
