.roc-image-viewport>img{width:100%;height:100%;object-fit:contain;display:block;transform-origin:center;user-select:none;pointer-events:none}
.roc-image-viewport[data-pannable=true]{cursor:grab;touch-action:none}.roc-image-viewport:active{cursor:grabbing}
.roc-image-tools{position:absolute;z-index:1;bottom:12px;left:50%;transform:translateX(-50%);display:flex;background:#fcfbf8e8;border:1px solid #ffffff80;border-radius:24px;padding:4px;gap:3px;backdrop-filter:blur(12px)}
.roc-image-tools button{border:0;background:none;padding:7px 11px;font:12px system-ui;min-width:36px}
.roc-voice{width:100%;color:#30332e}.roc-voice .voice-bar{display:flex;align-items:center;gap:12px;padding:16px;background:#fcfbf8;border:1px solid #e3e1da;border-radius:16px}
.roc-voice button{border:0;background:#eaece5;border-radius:50%;min-width:36px;height:36px;font:12px system-ui;flex:none}.roc-voice .voice-rate{border-radius:12px;background:transparent;min-width:32px}.roc-voice input{flex:1;min-width:20px;accent-color:#667e68;height:3px}.roc-voice .voice-time{font:11px system-ui;font-variant-numeric:tabular-nums;white-space:nowrap}.roc-voice [data-state=error] .voice-time{white-space:normal;color:#9d4935}.roc-voice button:disabled{opacity:.4}
.roc-selection-toolbar .notes-toolbar{position:fixed;z-index:200;display:flex;gap:3px;padding:7px;border-radius:24px;background:#292b28;color:white;box-shadow:0 8px 30px #0002;max-width:calc(100vw - 20px);overflow-x:auto}
.roc-selection-toolbar .notes-toolbar[hidden]{display:none}.roc-selection-toolbar button{border:0;background:none;color:inherit;border-radius:18px;min-width:32px;min-height:32px;font:13px system-ui}.roc-selection-toolbar button[aria-pressed=true]{background:#ffffff30}.roc-selection-toolbar button:disabled{opacity:.35}
.roc-page-book{width:100%;outline-offset:4px;color:#30312c}.roc-book-stage{height:calc(var(--book-h) + 18px);display:grid;place-items:center;touch-action:pan-y;user-select:none;cursor:grab;perspective:1800px}.roc-book{position:relative;width:calc(var(--book-w)*2);height:var(--book-h);transform-style:preserve-3d}.roc-page-book[data-mode=single] .roc-book{width:var(--book-w)}
