.roc-source-tray{height:300px;width:100%;position:relative}.roc-tray-layer{position:absolute;inset:0}.roc-tray-item{position:absolute;left:0;top:0;transform-origin:0 0;border:1px solid #e2dfd5;border-radius:8px;background:#fcfbf8;box-shadow:0 5px 16px #2221;overflow:hidden;padding:15px;box-sizing:border-box}.roc-tray-toggle{position:absolute;bottom:0;left:50%;transform:translateX(-50%);border:1px solid #dfded7;border-radius:25px;background:#fcfbf8;padding:9px 18px;font:12px system-ui}.roc-tray-item img{width:100%;height:100%;object-fit:cover}.roc-tray-item textarea{width:100%;height:100%;resize:none;border:0;background:none;font:16px/1.6 Georgia,serif}.roc-tray-item .roc-voice .voice-bar{padding:8px;border:0}.roc-tray-item p{font:14px/1.6 Georgia,serif}
.roc-selection-toolbar{position:fixed;inset:0;border:0;margin:0;padding:0;background:transparent;width:0;height:0;overflow:visible;pointer-events:none}.roc-selection-toolbar .notes-toolbar{pointer-events:auto}
